  section_name   TEXT PRIMARY KEY,
  status         TEXT NOT NULL,
  data           JSONB,
  observed_at    TIMESTAMPTZ,
  valid_until    TIMESTAMPTZ,
  source_freshness JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE IF NOT EXISTS private.provider_budget_counters (
  source       TEXT NOT NULL,
  usage_day    DATE NOT NULL,
  used_units   BIGINT NOT NULL DEFAULT 0 CHECK (used_units >= 0),
  PRIMARY KEY (source, usage_day)
);

CREATE TABLE IF NOT EXISTS private.provider_budget_reservations (
  source       TEXT NOT NULL,
  request_id   TEXT NOT NULL,
  usage_day    DATE NOT NULL,
  units        INTEGER NOT NULL CHECK (units > 0),
  reserved     BOOLEAN NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (source, request_id)
);

