CREATE OR REPLACE FUNCTION public.acquire_refresh_lease(
  p_lease_name TEXT,
  p_owner_id UUID,
  p_ttl_seconds INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_row private.refresh_leases%ROWTYPE;
BEGIN
  INSERT INTO private.refresh_leases (lease_name, owner_id, fence, expires_at, updated_at)
  VALUES (
    p_lease_name,
    p_owner_id,
    1,
    clock_timestamp() + make_interval(secs => greatest(coalesce(p_ttl_seconds, 1), 1)),
    clock_timestamp()
  )
  ON CONFLICT (lease_name) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        fence = private.refresh_leases.fence + 1,
        expires_at = EXCLUDED.expires_at,
        updated_at = clock_timestamp()
    WHERE private.refresh_leases.expires_at <= clock_timestamp()
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('acquired', false);
  END IF;
  RETURN jsonb_build_object(
    'acquired', true,
    'lease_name', v_row.lease_name,
    'owner_id', v_row.owner_id,
    'fence', v_row.fence,
    'expires_at', v_row.expires_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.release_refresh_lease(
  p_lease_name TEXT,
  p_owner_id UUID,
  p_fence BIGINT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_rows INTEGER;
BEGIN
  UPDATE private.refresh_leases
     SET expires_at = clock_timestamp(), updated_at = clock_timestamp()
   WHERE lease_name = p_lease_name
     AND owner_id = p_owner_id
     AND fence = p_fence;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.read_public_snapshot_sections()
RETURNS JSONB
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  SELECT coalesce(
    jsonb_object_agg(
      s.section_name,
      jsonb_build_object(
        'status', s.status,
        'data', s.data,
        'observed_at', s.observed_at,
        'valid_until', s.valid_until,
        'source_freshness', s.source_freshness
      )
    ),
    '{}'::jsonb
  )
  FROM private.public_snapshot_sections AS s;
$$;

CREATE OR REPLACE FUNCTION public.publish_public_dashboard_snapshot(
  p_lease_name TEXT,
  p_owner_id UUID,
  p_fence BIGINT,
  p_snapshot JSONB
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_lease private.refresh_leases%ROWTYPE;
  v_section RECORD;
  v_observed TIMESTAMPTZ;
  v_valid_until TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_lease
    FROM private.refresh_leases
   WHERE lease_name = p_lease_name
   FOR UPDATE;

  IF NOT FOUND
     OR v_lease.owner_id <> p_owner_id
     OR v_lease.fence <> p_fence
     OR v_lease.expires_at <= clock_timestamp()
     OR p_snapshot->>'snapshot_key' <> 'sumatra_mainland'
     OR (p_snapshot->>'schema_version')::INTEGER <> 1 THEN
    RETURN false;
  END IF;

  FOR v_section IN
    SELECT key, value
      FROM jsonb_each(coalesce(p_snapshot->'sections', '{}'::jsonb))
  LOOP
    IF v_section.value->>'status' IN ('ok', 'healthy')
       AND v_section.value ? 'data'
       AND v_section.value->'data' <> 'null'::jsonb THEN
      v_observed := NULLIF(v_section.value->>'observed_at', '')::TIMESTAMPTZ;
      v_valid_until := NULLIF(v_section.value->>'valid_until', '')::TIMESTAMPTZ;
      INSERT INTO private.public_snapshot_sections (
        section_name, status, data, observed_at, valid_until, source_freshness, updated_at
      ) VALUES (
        v_section.key,
        v_section.value->>'status',
        v_section.value->'data',
        v_observed,
        v_valid_until,
        coalesce(p_snapshot->'source_freshness'->v_section.key, '{}'::jsonb),
        clock_timestamp()
      )
      ON CONFLICT (section_name) DO UPDATE
        SET status = EXCLUDED.status,
            data = EXCLUDED.data,
            observed_at = EXCLUDED.observed_at,
            valid_until = EXCLUDED.valid_until,
            source_freshness = EXCLUDED.source_freshness,
            updated_at = EXCLUDED.updated_at;
    END IF;
  END LOOP;

  INSERT INTO public.public_dashboard_snapshots (snapshot_key, schema_version, computed_at, payload)
  VALUES (
    'sumatra_mainland',
    1,
    (p_snapshot->>'computed_at')::TIMESTAMPTZ,
    p_snapshot
  )
  ON CONFLICT (snapshot_key) DO UPDATE
    SET schema_version = EXCLUDED.schema_version,
        computed_at = EXCLUDED.computed_at,
        payload = EXCLUDED.payload;
  RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION public.complete_scheduled_job(
  p_job_name TEXT,
  p_owner_id UUID,
  p_fence BIGINT,
  p_status TEXT,
  p_error TEXT,
  p_retry_after_seconds INTEGER
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_lease private.refresh_leases%ROWTYPE;
  v_now TIMESTAMPTZ := clock_timestamp();
  v_rows INTEGER;
BEGIN
  SELECT * INTO v_lease
    FROM private.refresh_leases
   WHERE lease_name = 'scheduler_job:' || p_job_name
   FOR UPDATE;

  IF NOT FOUND
     OR v_lease.owner_id <> p_owner_id
     OR v_lease.fence <> p_fence
     OR v_lease.expires_at <= v_now THEN
    RETURN false;
  END IF;

  INSERT INTO public.scheduler_jobs (
    job_name, last_started_at, last_finished_at, last_status, last_error,
    locked_until, retry_after, updated_at
  ) VALUES (
    p_job_name, v_now,
    CASE WHEN p_status = 'ok' THEN v_now ELSE NULL END,
    p_status, NULLIF(left(coalesce(p_error, ''), 500), ''),
    NULL,
    CASE WHEN p_status = 'ok' THEN NULL
         ELSE v_now + make_interval(secs => greatest(coalesce(p_retry_after_seconds, 120), 1)) END,
    v_now
  )
  ON CONFLICT (job_name) DO UPDATE
    SET last_finished_at = CASE WHEN p_status = 'ok' THEN v_now ELSE public.scheduler_jobs.last_finished_at END,
        last_status = p_status,
        last_error = NULLIF(left(coalesce(p_error, ''), 500), ''),
        locked_until = NULL,
        retry_after = CASE WHEN p_status = 'ok' THEN NULL
                           ELSE v_now + make_interval(secs => greatest(coalesce(p_retry_after_seconds, 120), 1)) END,
        updated_at = v_now;

  UPDATE private.refresh_leases
     SET expires_at = v_now, updated_at = v_now
   WHERE lease_name = v_lease.lease_name
     AND owner_id = p_owner_id
     AND fence = p_fence;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.reserve_provider_budget(
  p_source TEXT,
  p_units INTEGER,
  p_request_id TEXT,
  p_daily_limit INTEGER
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_day DATE := (clock_timestamp() AT TIME ZONE 'UTC')::DATE;
  v_used BIGINT;
  v_existing BOOLEAN;
BEGIN
  IF coalesce(p_source, '') = ''
     OR coalesce(p_request_id, '') = ''
     OR coalesce(p_units, 0) <= 0
     OR coalesce(p_daily_limit, 0) <= 0 THEN
    RETURN false;
  END IF;

  INSERT INTO private.provider_budget_counters (source, usage_day, used_units)
  VALUES (p_source, v_day, 0)
  ON CONFLICT (source, usage_day) DO NOTHING;

  SELECT used_units INTO v_used
    FROM private.provider_budget_counters
   WHERE source = p_source AND usage_day = v_day
   FOR UPDATE;

  SELECT reserved INTO v_existing
    FROM private.provider_budget_reservations
   WHERE source = p_source AND request_id = p_request_id;
  IF FOUND THEN
    RETURN v_existing;
  END IF;

  IF v_used + p_units > p_daily_limit THEN
    INSERT INTO private.provider_budget_reservations (source, request_id, usage_day, units, reserved)
    VALUES (p_source, p_request_id, v_day, p_units, false)
    ON CONFLICT (source, request_id) DO NOTHING;
    RETURN false;
  END IF;

  INSERT INTO private.provider_budget_reservations (source, request_id, usage_day, units, reserved)
  VALUES (p_source, p_request_id, v_day, p_units, true)
  ON CONFLICT (source, request_id) DO NOTHING;
  IF NOT FOUND THEN
    SELECT reserved INTO v_existing
      FROM private.provider_budget_reservations
     WHERE source = p_source AND request_id = p_request_id;
    RETURN coalesce(v_existing, false);
  END IF;

  UPDATE private.provider_budget_counters
     SET used_units = used_units + p_units
   WHERE source = p_source AND usage_day = v_day;
  RETURN true;
END;
$$;

